// === Tab: mySketch ===
const COLOR01 = ["#14777F"];
const COLOR02 = ["#5EB8A5"];
const COLOR03 = ["#F6CCA5"];
const COLOR04 = ["#EBB444"];
const COLOR05 = ["#FA9075"];
const COLOR06 = ["#EE5176"];
const COLORS = [COLOR01, COLOR02, COLOR03, COLOR04, COLOR05, COLOR06];

let particles = [];

function setup() {
  createCanvas(windowWidth, windowHeight);
	background(0);
  for(let i = 0;i<200;i++){
    particles.push(new Particle());
	}
}

function draw() {
  background(0);
	stroke(255); noFill(); ellipse(width/2, height/2, 12, 12); 
  for(let i = 0; i < particles.length; i++) {
    particles[i].createParticle();
    particles[i].moveParticle();
    particles[i].joinParticles(particles.slice(i));
  }
}

class Particle {
  constructor(){
    this.ray = sqrt(sq(width/2)/2);
		this.x = random(width/2 - this.ray, width/2 + this.ray);
    this.y = random(height/2 - this.ray, height/2 + this.ray);
		this.distx = abs(width/2 - this.x);
		this.disty = abs(height/2 - this.y);
		this.distxy = sqrt(sq(this.distx) + sq(this.disty));
		this.distxyPlus = random(-1, 1);
    this.r = sqrt(sq(this.distx) + sq(this.disty))/20;
		this.angle = random(360);
		this.dir = int(random(0,2));
		this.anglePlus = random(0.0001, 0.002);
		this.color = random(COLORS);
  }

  createParticle() {
    stroke(this.color);
    fill(102,20);
    circle(this.x,this.y,this.r);
  }

  moveParticle() {
		if(this.dir == 0){
			this.angle += this.anglePlus * map(this.distxy, width/2, 0, 0.0001, 2);
		}else if(this.dir == 1){
			this.angle -= this.anglePlus * map(this.distxy, width/2, 0, 0.0001, 2);
		}
		this.distxy += this.distxyPlus;
		if (this.distxy > width/2 || this.distxy < 0){
			this.distxyPlus *= -1;
		}
    this.x =  width/2 + (sin(this.angle) * this.distxy);
		this.y =  height/2 + (cos(this.angle) * this.distxy);
  }

  joinParticles(particles) {
    particles.forEach(element =>{
      let dis = dist(this.x, this.y, element.x, element.y);
      if(dis < 60) {
        strokeWeight(1/*-dis/50*/); stroke(255-(dis*3)); line(this.x,this.y,element.x,element.y);
      }
    });
  }
}

